import pypdf

reader = pypdf.PdfReader("/root/sc100-blank.pdf")
fields = reader.get_fields()

checkboxes = [
    "SC-100[0].Page2[0].List1[0].Item1[0].Checkbox1[0]", # Filed before? Yes?
    "SC-100[0].Page2[0].List1[0].Item1[0].Checkbox2[0]", # Filed before? No?
    "SC-100[0].Page3[0].List4[0].Item4[0].Checkbox50[0]", # Demand Yes?
    "SC-100[0].Page3[0].List4[0].Item4[0].Checkbox50[1]", # Demand No?
    "SC-100[0].Page3[0].List5[0].Lia[0].Checkbox5cb[0]"   # Venue: Def lives here?
]

if fields:
    for cb in checkboxes:
        if cb in fields:
            print(f"Field: {cb}, Value: {fields[cb].get('/V')}, Options: {fields[cb].get('/Opt')}, Kids: {fields[cb].get('/Kids')}")
        else:
            print(f"Field {cb} not found directly.")

# Also inspect all checkboxes to see their mapping
print("\n--- All Button Fields ---")
for name, field in fields.items():
    if field.get('/FT') == '/Btn':
        print(f"Name: {name}, Parent: {field.get('/Parent')}, AA: {field.get('/AA')}, AP: {field.get('/AP')}")

